import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Bag<String> words = new Bag<>();
        while (sc.hasNext()) {
            words.add(sc.next());
        }

        if (words.isEmpty()) {
            System.out.println("No words");
            return;
        }
        Pair<String, Integer> summary = new Pair<>(words.get(0), words.size());
        System.out.println(summary);
        System.out.println("First: " + summary.getFirst());
        System.out.println("Count: " + summary.getSecond());

        Bag<Integer> lengths = new Bag<>();  // Integer, never int
        for (int i = 0; i < words.size(); i++) {
            lengths.add(words.get(i).length());
        }
        System.out.println("Lengths: " + lengths);
    }
}

class Bag<T> {
    private final List<T> items = new ArrayList<>();

    void add(T item) {
        items.add(item);
    }

    T get(int index) {
        return items.get(index);
    }

    int size() {
        return items.size();
    }

    boolean isEmpty() {
        return items.isEmpty();
    }

    @Override
    public String toString() {
        return items.toString();
    }
}

class Pair<A, B> {
    private final A first;
    private final B second;

    Pair(A first, B second) {
        this.first = first;
        this.second = second;
    }

    A getFirst() {
        return first;
    }

    B getSecond() {
        return second;
    }

    @Override
    public String toString() {
        return "(" + first + ", " + second + ")";
    }
}

