import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> words = new ArrayList<>();
        for (String part : br.readLine().strip().split("\\s+")) {
            words.add(part);
        }
        List<Integer> nums = new ArrayList<>();
        for (String part : br.readLine().strip().split("\\s+")) {
            nums.add(Integer.parseInt(part));
        }

        System.out.println("Last word: " + lastOf(words));   // T is String
        System.out.println("Last number: " + lastOf(nums));  // T is Integer
        swap(words, 0, words.size() - 1);
        swap(nums, 0, nums.size() - 1);
        System.out.println("Words: " + words);
        System.out.println("Numbers: " + nums);

        Map<String, Integer> lengths = new TreeMap<>();
        for (String w : words) {
            lengths.put(w, w.length());
        }
        System.out.println("fig -> " + getOr(lengths, "fig", 0));
        System.out.println("plum -> " + getOr(lengths, "plum", 0));
    }

    static <T> T lastOf(List<T> items) {
        return items.get(items.size() - 1);
    }

    static <T> void swap(List<T> items, int i, int j) {
        T temp = items.get(i);
        items.set(i, items.get(j));
        items.set(j, temp);
    }

    static <K, V> V getOr(Map<K, V> map, K key, V fallback) {
        return map.containsKey(key) ? map.get(key) : fallback;
    }
}

