import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> words = new ArrayList<>();
        for (String part : br.readLine().strip().split("\\s+")) {
            words.add(part);
        }
        List<Integer> ints = new ArrayList<>();
        for (String part : br.readLine().strip().split("\\s+")) {
            ints.add(Integer.parseInt(part));
        }
        List<Double> doubles = new ArrayList<>();
        for (String part : br.readLine().strip().split("\\s+")) {
            doubles.add(Double.parseDouble(part));
        }

        System.out.println("Max word: " + maxOf(words));
        System.out.println("Max number: " + maxOf(ints));
        System.out.printf("Int sum: %.2f%n", sumAll(ints));
        System.out.printf("Double sum: %.2f%n", sumAll(doubles));
        // List<Number> numbers = ints;  // compile error: generics are invariant
    }

    static <T extends Comparable<T>> T maxOf(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) {
                best = item;
            }
        }
        return best;
    }

    static double sumAll(List<? extends Number> values) {
        double total = 0;
        for (Number value : values) {
            total += value.doubleValue();
        }
        return total;
    }
}

